mapper.select:
SELECT 
  FROM MERCHANT_MASTER m
 WHERE m.MERCHANT_ID = #{merchantId}

SELECT FROM MERCHANT_MASTER m
AND UPPER(m.LEGAL_NAME) LIKE '%' || UPPER(#{nameLike}) || '%'
AND m.MCC = #{mcc}
AND m.ACQUIRER_ID = #{acquirerId}
AND m.ACTIVE_FLAG = 'Y'
ORDER BY m.LEGAL_NAME FETCH FIRST #{limit} ROWS ONLY
